--- a/src/cmsopt.c
+++ b/src/cmsopt.c
@@ -1698,6 +1698,12 @@
               // Input offset should be zero
               if (Data1->Offset != NULL) return FALSE;

+              // This optimization assumes full 3x3 matrices. Malformed pipelines may
+              // carry matrix payloads sized to stage channels (e.g. non-3x3), so avoid
+              // treating them as cmsMAT3 unless dimensions match exactly.
+              if (Matrix1->InputChannels != 3 || Matrix1->OutputChannels != 3) return FALSE;
+              if (Matrix2->InputChannels != 3 || Matrix2->OutputChannels != 3) return FALSE;
+
               // Multiply both matrices to get the result
               _cmsMAT3per(&res, (cmsMAT3*)Data2->Double, (cmsMAT3*)Data1->Double);

@@ -1720,6 +1726,12 @@

                      _cmsStageMatrixData* Data = (_cmsStageMatrixData*)cmsStageData(Matrix1);

+                     // This optimization path also requires a true 3x3 matrix payload.
+                     if (Matrix1->InputChannels != 3 || Matrix1->OutputChannels != 3)
+                            return FALSE;
+                     if (Data == NULL || Data->Double == NULL)
+                            return FALSE;
+
                      // Copy the matrix to our result
                      memcpy(&res, Data->Double, sizeof(res));

